  "No pending invitations.": "\u0644\u0627 \u062A\u0648\u062C\u062F \u062F\u0639\u0648\u0627\u062A \u0645\u0639\u0644\u0642\u0629.",
  "Command palette": "\u0644\u0648\u062D\u0629 \u0627\u0644\u0623\u0648\u0627\u0645\u0631",
