  "Report a Bug": "\u0627\u0644\u0625\u0628\u0644\u0627\u063A \u0639\u0646 \u062E\u0637\u0623",
  "Found a bug? Help us fix it. Provide as much detail as possible.": "\u0648\u062C\u062F\u062A \u062E\u0637\u0623\u061F \u0633\u0627\u0639\u062F\u0646\u0627 \u0639\u0644\u0649 \u0625\u0635\u0644\u0627\u062D\u0647 \u0648\u0642\u062F\u0651\u0645 \u0623\u0643\u0628\u0631 \u0642\u062F\u0631 \u0645\u0645\u0643\u0646 \u0645\u0646 \u0627\u0644\u062A\u0641\u0627\u0635\u064A\u0644.",
  "Severity": "\u0627\u0644\u062E\u0637\u0648\u0631\u0629",
  "Bug severity": "\u062E\u0637\u0648\u0631\u0629 \u0627\u0644\u062E\u0637\u0623",
  "Low - Minor issue, not blocking": "\u0645\u0646\u062E\u0641\u0636 - \u0645\u0634\u0643\u0644\u0629 \u0628\u0633\u064A\u0637\u0629 \u0644\u0627 \u062A\u0639\u064A\u0642 \u0627\u0644\u0639\u0645\u0644",
  "Medium - Affects workflow": "\u0645\u062A\u0648\u0633\u0637 - \u062A\u0624\u062B\u0631 \u0639\u0644\u0649 \u0633\u064A\u0631 \u0627\u0644\u0639\u0645\u0644",
  "High - Major feature broken": "\u0645\u0631\u062A\u0641\u0639 - \u0645\u064A\u0632\u0629 \u0631\u0626\u064A\u0633\u064A\u0629 \u0645\u0639\u0637\u0644\u0629",
  "Critical - App unusable": "\u062D\u0631\u062C - \u0627\u0644\u062A\u0637\u0628\u064A\u0642 \u063A\u064A\u0631 \u0642\u0627\u0628\u0644 \u0644\u0644\u0627\u0633\u062A\u062E\u062F\u0627\u0645",
  "Affected Tool": "\u0627\u0644\u0623\u062F\u0627\u0629 \u0627\u0644\u0645\u062A\u0623\u062B\u0631\u0629",
  "Affected tool": "\u0627\u0644\u0623\u062F\u0627\u0629 \u0627\u0644\u0645\u062A\u0623\u062B\u0631\u0629",
  "General / Platform": "\u0639\u0627\u0645 / \u0627\u0644\u0645\u0646\u0635\u0629",
  "CV Builder": "\u0645\u0646\u0634\u0626 \u0627\u0644\u0633\u064A\u0631\u0629 \u0627\u0644\u0630\u0627\u062A\u064A\u0629",
  "Cover Letter": "\u062E\u0637\u0627\u0628 \u0627\u0644\u062A\u063A\u0637\u064A\u0629",
  "Translator": "\u0627\u0644\u0645\u062A\u0631\u062C\u0645",
  "Login / Signup": "\u062A\u0633\u062C\u064A\u0644 \u0627\u0644\u062F\u062E\u0648\u0644 / \u0627\u0644\u062A\u0633\u062C\u064A\u0644",
  "Steps to Reproduce": "\u062E\u0637\u0648\u0627\u062A \u0625\u0639\u0627\u062F\u0629 \u0627\u0644\u0645\u0634\u0643\u0644\u0629",
  "Expected Behavior": "\u0627\u0644\u0633\u0644\u0648\u0643 \u0627\u0644\u0645\u062A\u0648\u0642\u0639",
  "Actual Behavior": "\u0627\u0644\u0633\u0644\u0648\u0643 \u0627\u0644\u0641\u0639\u0644\u064A",
  "Help Center": "\u0645\u0631\u0643\u0632 \u0627\u0644\u0645\u0633\u0627\u0639\u062F\u0629",
  "Find answers to common questions and get support.": "\u0627\u0639\u062B\u0631 \u0639\u0644\u0649 \u0625\u062C\u0627\u0628\u0627\u062A \u0644\u0644\u0623\u0633\u0626\u0644\u0629 \u0627\u0644\u0634\u0627\u0626\u0639\u0629 \u0648\u0627\u062D\u0635\u0644 \u0639\u0644\u0649 \u0627\u0644\u062F\u0639\u0645.",
  "No results found. Try a different search.": "\u0644\u0645 \u064A\u062A\u0645 \u0627\u0644\u0639\u062B\u0648\u0631 \u0639\u0644\u0649 \u0646\u062A\u0627\u0626\u062C. \u062C\u0631\u0651\u0628 \u0628\u062D\u062B\u0627\u064B \u0645\u062E\u062A\u0644\u0641\u0627\u064B.",
  "Still need help?": "\u0645\u0627 \u0632\u0644\u062A \u062A\u062D\u062A\u0627\u062C \u0644\u0644\u0645\u0633\u0627\u0639\u062F\u0629\u061F",
  "Send us a message and we'll get back to you within 24 hours.": "\u0623\u0631\u0633\u0644 \u0644\u0646\u0627 \u0631\u0633\u0627\u0644\u0629 \u0648\u0633\u0646\u0631\u062F \u0639\u0644\u064A\u0643 \u062E\u0644\u0627\u0644 24 \u0633\u0627\u0639\u0629.",
  "Search help articles...": "\u0627\u0628\u062D\u062B \u0641\u064A \u0645\u0642\u0627\u0644\u0627\u062A \u0627\u0644\u0645\u0633\u0627\u0639\u062F\u0629...",
  "Describe your issue...": "\u0635\u0641 \u0645\u0634\u0643\u0644\u062A\u0643...",
