  "Privacy Policy": "\u0633\u064A\u0627\u0633\u0629 \u0627\u0644\u062E\u0635\u0648\u0635\u064A\u0629",
  "Necessary": "\u0636\u0631\u0648\u0631\u064A\u0629",
  "Analytics": "\u0627\u0644\u062A\u062D\u0644\u064A\u0644\u0627\u062A",
